"""Generated by the NL to Flow Diagram Encoder Pipeline."""

def SECOND_LARGEST(arr):
    max = float('-inf')
    second_max = float('-inf')
    for num in arr:
        if (num > max):
            second_max = max
            max = num
        elif ((num > second_max) and (num != max)):
            second_max = num
    return second_max

print(SECOND_LARGEST([1, 20, 30, 4, 5]))
print(SECOND_LARGEST([8, 4, 6, 2, 10]))